function f_{SUT}_CMN_PR_InitConfiguration_001() runs on {SUT}Tester {
    // Phase A: Map ports
    map(mtc:pt_V2G_TCP_TLS_ALM_{SUT}_Port, system:pt_V2G_TCP_TLS_ALM_{SUT}_Port);
    map(mtc:pt_V2G_UDP_SDP_Port, system:pt_V2G_UDP_SDP_Port);

    // Phase B: SDP Discovery via UDP multicast
    // V2GTP header: version=01, inv=FE, payloadType=9000(SDP), length=4, body=2100
    var octetstring sdp_req := '01FE9000000000021000'O;
    pt_V2G_UDP_SDP_Port.send(sdp_req);

    timer t_sdp;
    t_sdp.start(5.0);

    alt {
        [] pt_V2G_UDP_SDP_Port.receive {
            t_sdp.stop;
            log("SDP discovery: SECC found via UDP multicast");
        }
        [] t_sdp.timeout {
            log("SDP discovery: timeout, proceeding anyway (SIL mode)");
        }
    }

    log("InitConfiguration complete, SDP discovery done");
    return pass;
}

// STEP 1: Lookup exi_payload_library.json for wire_hex, is_dynamic, json_payload
// STEP 2: Locate md_CMN_{Msg}Req_001 in SECC_CmnTemplates.ttcn
// STEP 3: Send via V2G_PortMessage v2g variant -- ExiCodecAdapter handles V2GTP header + EXI encoding
pt_V2G_TCP_TLS_ALM_{SUT}_Port.send(
    { v2g := { supportedAppProtocolReq := md_CMN_SupportedAppProtocolReq_001 } }
);

// TCP connect block (handled by port adapter based on set_parameter ip_address/port)
// The C++ port adapter reads V2G__UDP__SDP__Port__last_secc_ip_ and V2G__UDP__SDP__Port__last_secc_port_
// to determine the TCP destination after SDP response is received.
// In TTCN-3: just ensure the port is mapped -- TCP connection is established on first send() using shared SDP state.
map(mtc:pt_V2G_TCP_TLS_ALM_{SUT}_Port, system:pt_V2G_TCP_TLS_ALM_{SUT}_Port);
map(mtc:pt_V2G_UDP_SDP_Port, system:pt_V2G_UDP_SDP_Port);

// ================================================================
// V2GTP Header BadCase: send malformed V2GTP header as raw octetstring
//
// V2GTP header format (8 bytes):
//   byte 0: ProtocolVersion        -- must be 0x01 (BadCase: send 0x02)
//   byte 1: InverseProtocolVersion -- must be 0xFE = 0x01 xor 0xFF (BadCase: 0xFD)
//   byte 2-3: PayloadType          -- 0x8001=EXI, 0x9000=SDP (BadCase: any other)
//   byte 4-7: PayloadLength        -- big-endian 32-bit
//
// The C++ adapter sends this bytes-as-is (no EXI encoding, no V2GTP patching).
// ================================================================
timer tc_msg := PX_SECC_CMN_Message_Timeout;
tc_msg.start(PX_SECC_CMN_Message_Timeout);

// Example TC_SECC_CMN_VTB_V2GTPHeader_002: ProtocolVersion=0x02 (invalid)
var octetstring v2gtp_malformed := '0201FD0200000002'O;  // Ver=02,Inv=FD,Type=8001,Len=2,payload=0000
pt_V2G_TCP_TLS_ALM_SECC_Port.send({ raw := v2gtp_malformed });

alt {
    [] pt_V2G_TCP_TLS_ALM_SECC_Port.receive(?) {
        tc_msg.stop;
        setverdict(fail, "SECC accepted invalid ProtocolVersion -- V2G2-082 violation");
    }
    [] tc_msg.timeout {
        setverdict(pass, "SECC correctly rejected invalid ProtocolVersion (timeout/close)");
    }
}
return getverdict;

timer tc_msg := {timer_value};
tc_msg.start;
pt_V2G_TCP_TLS_ALM_{SUT}_Port.send({ v2g := { msgType := md_CMN_MsgReq_001 } });
alt {
    [] pt_V2G_TCP_TLS_ALM_{SUT}_Port.receive({ resType := mdw_{SUT}_MsgRes_001 }) {
        tc_msg.stop;
        setverdict(pass, "{success_message}");
    }
    [] pt_V2G_TCP_TLS_ALM_{SUT}_Port.receive(?) {
        tc_msg.stop;
        setverdict(fail, "{failure_message}");
    }
    [] tc_msg.timeout {
        setverdict(inconc, "Timeout waiting for response");
    }
}
return getverdict;

// Phase A: Map ports (at beginning of testcase)
map(mtc:pt_V2G_TCP_TLS_ALM_{SUT}_Port, system:pt_V2G_TCP_TLS_ALM_{SUT}_Port);
map(mtc:pt_V2G_UDP_SDP_Port, system:pt_V2G_UDP_SDP_Port);

// Phase D: Unmap ports (at end of testcase, unconditional)
f_{SUT}_CMN_PO_InitialState_001();
f_{SUT}_CMN_PO_ShutdownConfiguration_001();
unmap(mtc:pt_V2G_TCP_TLS_ALM_{SUT}_Port, system:pt_V2G_TCP_TLS_ALM_{SUT}_Port);
unmap(mtc:pt_V2G_UDP_SDP_Port, system:pt_V2G_UDP_SDP_Port);

// GoodCase: expect valid response
var verdicttype v_result;
timer tc_msg := PX_SECC_CMN_Message_Timeout;
tc_msg.start;
pt_V2G_TCP_TLS_ALM_SECC_Port.send({ v2g := { msgType := md_CMN_MsgReq_001 } });
alt {
    [] pt_V2G_TCP_TLS_ALM_SECC_Port.receive({ resType := ? }) {
        tc_msg.stop;
        setverdict(pass, "Response matches expected");
        v_result := pass;
    }
    [] pt_V2G_TCP_TLS_ALM_SECC_Port.receive(?) {
        tc_msg.stop;
        setverdict(fail, "Unexpected response received");
        v_result := fail;
    }
    [] tc_msg.timeout {
        setverdict(inconc, "Timeout waiting for response");
        v_result := inconc;
    }
}
return getverdict;

// BadCase: expect SUT to reject/ignore/close
var verdicttype v_result;
timer tc_msg := PX_SECC_CMN_Message_Timeout;
tc_msg.start;
// Send malformed message via raw variant (V2GTP header BadCase)
pt_V2G_TCP_TLS_ALM_SECC_Port.send({ raw := '0201FD0200000002'O });
alt {
    [] pt_V2G_TCP_TLS_ALM_SECC_Port.receive(?) {
        tc_msg.stop;
        setverdict(fail, "SUT should reject this invalid input");
        v_result := fail;
    }
    [] tc_msg.timeout {
        setverdict(pass, "SUT correctly ignored invalid input (timeout)");
        v_result := pass;
    }
}
return getverdict;

function f_{SUT}_{Category}_TB_VTB_{MessageType}_{SeqNo}()
    runs on {SUT}Tester
    return verdicttype
{
    timer tc_msg := PX_SECC_CMN_Message_Timeout;

    // Send via V2G_PortMessage v2g variant -- ExiCodecAdapter handles V2GTP header + EXI encoding
    tc_msg.start(PX_SECC_CMN_Message_Timeout);
    pt_V2G_TCP_TLS_ALM_{SUT}_Port.send(
        { v2g := { msgType := md_CMN_{MessageType}Req_001 } }
    );

    // Receive and set verdict
    alt {
        [] pt_V2G_TCP_TLS_ALM_{SUT}_Port.receive(
            { resType := ? }
        ) {
            tc_msg.stop;
            log("{MessageType}Res received and matched");
            log("SessionID captured (C++ adapter stores it for subsequent messages)");
            setverdict(pass, "{MessageType} exchange successful");
        }
        [] pt_V2G_TCP_TLS_ALM_{SUT}_Port.receive {
            tc_msg.stop;
            setverdict(fail, "Unexpected message received during {MessageType}");
        }
        [] tc_msg.timeout {
            setverdict(inconc, "Timeout waiting for {MessageType}Res");
        }
    }

    return getverdict;
}

function f_{SUT}_CMN_PR_{MessageName}_{SeqNo}()
    runs on {SUT}Tester
    return verdicttype
{
    timer tc_msg := PX_SECC_CMN_Message_Timeout;

    log("Sending {MessageName}Req via V2G_PortMessage v2g variant...");
    tc_msg.start(PX_SECC_CMN_Message_Timeout);

    // STEP 3: Send via V2G_PortMessage v2g variant -- ExiCodecAdapter encodes
    pt_V2G_TCP_TLS_ALM_{SUT}_Port.send(
        { v2g := { {msgName}Req := md_CMN_{MessageName}Req_001 } }
    );

    // STEP 4: Receive and set verdict
    alt {
        [] pt_V2G_TCP_TLS_ALM_{SUT}_Port.receive(
            { {msgName}Res := md_CMN_{MessageName}Res_001 }
        ) {
            tc_msg.stop;
            log("{MessageName}Res received: exchange complete");
            setverdict(pass, "{MessageName} exchange successful");
        }
        [] pt_V2G_TCP_TLS_ALM_{SUT}_Port.receive(
            { {msgName}Res := md_CMN_{MessageName}Res_002 }
        ) {
            tc_msg.stop;
            setverdict(fail, "SECC rejected the {MessageName} negotiation");
        }
        [] tc_msg.timeout {
            setverdict(inconc, "Timeout waiting for {MessageName}Res");
        }
    }

    return getverdict;
}

// Phase A+B: PreConditions
var verdicttype preConVerdict;
if (f_SECC_CMN_PR_InitConfiguration_001() != pass) {
    preConVerdict := fail;
} else {
    preConVerdict := f_SECC_CMN_PR_SupportedAppProtocol_001();
}
if (preConVerdict != pass) {
    setverdict(inconc);
    f_SECC_CMN_PO_InitialState_001();
    f_SECC_CMN_PO_ShutdownConfiguration_001();
    return;
}

// Phase C: Test behavior (only if preconditions passed)
f_SECC_CMN_TB_VTB_{MsgType}_{SeqNo}();

// Phase D: Postconditions (ALWAYS runs, regardless of preConVerdict or v_result)
f_SECC_CMN_PO_InitialState_001();
f_SECC_CMN_PO_ShutdownConfiguration_001();
unmap(mtc:pt_V2G_TCP_TLS_ALM_SECC_Port, system:pt_V2G_TCP_TLS_ALM_SECC_Port);
unmap(mtc:pt_V2G_UDP_SDP_Port, system:pt_V2G_UDP_SDP_Port);
stop;

