// LLM generates TTCN-3 union only. C++ adapter forwards to microservice.
pt_V2G_TCP_TLS_ALM_{SUT}_Port.send(
    { v2g := { {msgType}Req := md_CMN_{MsgType}Req_001 } }
);

// ==============================================================
// ISO15118 SessionID State Machine -- MANDATORY PATTERN
// ==============================================================
// C++ adapter: STATELESS translator (zero SessionID memory)
// TTCN-3: SOLE owner of SessionID state
// Flow: receive -> Extract -> Persist (vc_) -> Inject -> send
// ==============================================================

// --- STEP 1: Extract + Persist (inside alt branch of PR function) ---
alt {
    [] pt_V2G_TCP_TLS_ALM_SECC_Port.receive(
        { sessionSetupRes := md_CMN_SessionSetupRes_001 }  // explicit union branch match
    ) -> value v_res {
        tc_msg.stop;
        // Persist: assign to component variable immediately
        if (ispresent(v_res.sessionID.content)) {
            vc_SessionID := v_res.sessionID.content;
        }
        setverdict(pass, "SessionSetup OK, SessionID stored in vc_SessionID");
    }
    [] pt_V2G_TCP_TLS_ALM_SECC_Port.receive(
        { sessionSetupRes := md_CMN_SessionSetupRes_002 }   // FAILED_NewSessionStarted
    ) {
        tc_msg.stop;
        if (ispresent(v_res.sessionID.content)) {
            vc_SessionID := v_res.sessionID.content;
        }
        setverdict(fail, "SECC rejected SessionSetup");
    }
    [] tc_msg.timeout {
        setverdict(inconc, "SessionSetup timeout");
    }
}

// --- STEP 2: Inject + Send (inside TB function) ---
// Use valueof(template) as intermediate record, inject vc_, wrap in Union
var ServiceDiscoveryReq v_sd_req := valueof(md_CMN_ServiceDiscoveryReq_001);
v_sd_req.sessionID.content := vc_SessionID;  // inject persisted value
pt_V2G_TCP_TLS_ALM_SECC_Port.send({ serviceDiscoveryReq := v_sd_req });

