// ==============================================================
// TTCN3_Stateless_EPI_Pattern -- MANDATORY (protocol-agnostic)
// Extract -> Persist -> Inject
// ==============================================================

// ---- A. Component variable declaration (ComponentsAndPorts.ttcn) ----
type component SECCTester {
    port V2G_TCP_TLS_Port pt_V2G_TCP_TLS_ALM_SECC_Port;
    port V2G_UDP_SDP_Port pt_V2G_UDP_SDP_Port;

    // vc_ prefix is mandatory; names match the union field they mirror
    var octetstring  vc_SessionID         := '0000000000000000'O;
    var octetstring  vc_EVSEID            := ''O;
    var integer      vc_SAScheduleTupleID := 0;
}

// ---- B. Extract + Persist (inside PreCondition alt-branch) ----
alt {
    [] pt_V2G_TCP_TLS_ALM_SECC_Port.receive(
        { sessionSetupRes := md_CMN_SessionSetupRes_001 }
    ) -> value v_res {
        tc_msg.stop;
        // Persist: gate with ispresent, then assign to vc_
        if (ispresent(v_res.sessionID.content)) {
            vc_SessionID := v_res.sessionID.content;
        }
        if (ispresent(v_res.EVSEID)) {
            vc_EVSEID := v_res.EVSEID;
        }
        setverdict(pass, "SessionSetup OK; state persisted to vc_ variables");
    }
    [] tc_msg.timeout {
        setverdict(inconc, "SessionSetup timeout");
    }
}

// ---- C. Inject + Send (inside TestBehavior) ----
var ServiceDiscoveryReq v_sd_req := valueof(md_CMN_ServiceDiscoveryReq_001);
v_sd_req.sessionID.content := vc_SessionID;  // inject persisted value
pt_V2G_TCP_TLS_ALM_SECC_Port.send(
    { v2g := { serviceDiscoveryReq := v_sd_req } }
);
